import { plainText } from "../text";

// Roadmap Phase 8: export the owner-approved Blueprint into files agents and other tools read: a managed section of
// AGENTS.md, OpenSpec specs (openspec/specs/<slug>/spec.md) or Spec Kit specs (specs/<nnn>-<slug>/spec.md).
// Deterministic, no AI. Every generated file starts with GENERATED_MARK, so `codeceipt export` only ever rewrites files
// it wrote; AGENTS.md keeps everything outside the marked section. Text from the Blueprint is one line and can never
// add a heading, a list, HTML or a marker of its own.

export const EXPORT_TARGETS = ["agents", "openspec", "speckit"] as const;
export type ExportTarget = (typeof EXPORT_TARGETS)[number];
export type ExportCriterion = { text: string; kind: string };
export type ExportFeature = {
  name: string;
  purpose: string | null;
  dependsOn: string[];
  criteria: ExportCriterion[];
};
export type ExportBoundary = { kind: string; pattern: string };
export type ExportBlueprint = {
  version: number;
  features: ExportFeature[];
  boundaries: ExportBoundary[];
};

export const GENERATED_MARK =
  "<!-- generated by codeceipt export: edit the Blueprint, not this file -->";
export const SECTION_START =
  "<!-- codeceipt:blueprint:start (generated by codeceipt export: edit the Blueprint, not this section) -->";
export const SECTION_END = "<!-- codeceipt:blueprint:end -->";
const START_PREFIX = "<!-- codeceipt:blueprint:start";
const MAX_FEATURES = 500;
const MAX_CRITERIA = 30;
const MAX_BOUNDARIES = 100;

const KIND_LABEL: Record<string, string> = {
  must_never: "Must never",
  security: "Security",
};
const BOUNDARY_LABEL: Record<string, string> = {
  protected_path: "Protected path (agents never edit it)",
  allowed_dependency: "Allowed package",
  disallowed_dependency: "Package not allowed",
};

/** One plain line of Markdown text: no HTML, no markers, no heading or list syntax, no table pipes. */
export function mdText(value: string, max = 300): string {
  return plainText(value)
    .slice(0, max)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/\\/g, "\\\\")
    .replace(/[|[\]`]/g, "\\$&")
    .replace(/^([#+\-=~])/, "\\$1")
    .replace(/^(\d+)([.)])/, "$1\\$2");
}
/** A path or package name in inline code; a backtick in it would end the code span, so it becomes a quote. */
const code = (value: string) => `\`${plainText(value).slice(0, 200).replace(/`/g, "'")}\``;

export function slug(name: string, taken: Set<string>): string {
  const base =
    plainText(name)
      .toLowerCase()
      .normalize("NFKD")
      .replace(/\p{M}/gu, "")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 50)
      .replace(/-+$/, "") || "feature";
  let s = base;
  for (let n = 2; taken.has(s); n++) s = `${base}-${n}`;
  taken.add(s);
  return s;
}

const features = (bp: ExportBlueprint) =>
  bp.features
    .slice(0, MAX_FEATURES)
    .map((f) => ({ ...f, criteria: f.criteria.slice(0, MAX_CRITERIA) }));
const label = (c: ExportCriterion) => (KIND_LABEL[c.kind] ? `${KIND_LABEL[c.kind]}: ` : "");

/** The managed AGENTS.md section (markers included). */
export function agentsSection(bp: ExportBlueprint): string {
  const lines = [
    SECTION_START,
    `## Blueprint (version ${Math.max(0, Math.trunc(bp.version))})`,
    "The owner-approved features and their criteria: what done means for each one.",
    "",
  ];
  for (const [i, f] of features(bp).entries()) {
    lines.push(`### ${i + 1}. ${mdText(f.name, 100)}`);
    if (f.purpose) lines.push(mdText(f.purpose));
    if (f.dependsOn.length > 0)
      lines.push(
        `After: ${f.dependsOn
          .slice(0, 20)
          .map((d) => mdText(d, 100))
          .join(", ")}`,
      );
    for (const c of f.criteria) lines.push(`- ${label(c)}${mdText(c.text)}`);
    lines.push("");
  }
  const bounds = bp.boundaries.slice(0, MAX_BOUNDARIES);
  if (bounds.length > 0) {
    lines.push("### Boundaries");
    for (const b of bounds)
      lines.push(`- ${BOUNDARY_LABEL[b.kind] ?? mdText(b.kind, 40)}: ${code(b.pattern)}`);
    lines.push("");
  }
  lines.push(SECTION_END);
  return lines.join("\n");
}

/**
 * AGENTS.md with the section added or replaced; everything outside the markers is kept. Null when the markers are
 * broken (one without the other, out of order or more than one section): the file is then left alone.
 */
export function mergeAgents(existing: string | null, section: string): string | null {
  if (existing === null || existing.trim() === "") return `${section}\n`;
  const starts = existing.split(START_PREFIX).length - 1;
  const ends = existing.split(SECTION_END).length - 1;
  if (starts === 0 && ends === 0) return `${existing.replace(/\s*$/, "")}\n\n${section}\n`;
  if (starts !== 1 || ends !== 1) return null;
  const s = existing.indexOf(START_PREFIX);
  const e = existing.indexOf(SECTION_END);
  if (e < s) return null;
  return existing.slice(0, s) + section + existing.slice(e + SECTION_END.length);
}

function openSpec(f: ExportFeature): string {
  const lines = [
    GENERATED_MARK,
    `# ${mdText(f.name, 100)}`,
    "",
    "## Purpose",
    mdText(f.purpose ?? "") || "From the Codeceipt Blueprint.",
    "",
    "## Requirements",
  ];
  for (const c of f.criteria) {
    const text = mdText(c.text);
    lines.push("", `### Requirement: ${text.slice(0, 80)}`, `${label(c)}${text}`);
  }
  return `${lines.join("\n")}\n`;
}

function specKit(f: ExportFeature): string {
  const lines = [
    GENERATED_MARK,
    `# Feature Specification: ${mdText(f.name, 100)}`,
    "",
    "## Requirements",
    "",
    "### Functional Requirements",
  ];
  for (const [i, c] of f.criteria.entries()) {
    lines.push(`- **FR-${String(i + 1).padStart(3, "0")}**: ${label(c)}${mdText(c.text)}`);
  }
  return `${lines.join("\n")}\n`;
}

/** The files for OpenSpec or Spec Kit, by repo-relative path (one per feature, in build order). */
export function specFiles(
  target: "openspec" | "speckit",
  bp: ExportBlueprint,
): Map<string, string> {
  const out = new Map<string, string>();
  const taken = new Set<string>();
  for (const [i, f] of features(bp).entries()) {
    const s = slug(f.name, taken);
    if (target === "openspec") out.set(`openspec/specs/${s}/spec.md`, openSpec(f));
    else out.set(`specs/${String(i + 1).padStart(3, "0")}-${s}/spec.md`, specKit(f));
  }
  return out;
}

/** True when a file is one `codeceipt export` wrote (so it may be rewritten). */
export const isGenerated = (text: string) => text.startsWith(GENERATED_MARK);
